function link(href: string, label: string, primary = false): string {
  return `<a class="action${primary ? " primary" : ""}" href="${href}">${label}</a>`;
}

function renderJourneyStepper(page: JourneyPage, language: "ta" | "en", state: JourneyState): string {
  const en = language === "en";
  const stages: { id: JourneyPage; num: number; label: [string, string]; title: [string, string] }[] = [
    { id: "awareness", num: 1, label: ["அறிமுகம்", "Basics"], title: ["பொறியியல் அறிமுகம்", "Engineering Introduction"] },
    { id: "study", num: 2, label: ["துறைகள்", "Branches"], title: ["நாம் என்ன படிப்போம்?", "What will we study?"] },
    { id: "compare", num: 3, label: ["ஒப்பீடு", "Compare"], title: ["துறைகள் ஒப்பீடு", "Compare Fields"] },
    { id: "route", num: 4, label: ["சேர்க்கை வழி", "TNEA Route"], title: ["TNEA சேர்க்கை வழி", "TNEA Admission Route"] },
    { id: "prepare", num: 5, label: ["தயாரிப்பு", "Prepare"], title: ["விண்ணப்பத் தயாரிப்பு", "Prepare to Apply"] },
  ];

  const currentIdx = stages.findIndex((s) => s.id === page);
  const isCheck = page === "check";
  const stepNum = isCheck ? 5 : (currentIdx >= 0 ? currentIdx + 1 : 1);
  const progressPercent = isCheck ? 100 : Math.round((stepNum / 5) * 100);

  const stepBadge = isCheck
    ? (en ? "Deep-Dive Check" : "தகுதிச் சரிபார்ப்பு")
    : (en ? `Step ${stepNum} of 5` : `படி ${stepNum} / 5`);

  const stepTitle = isCheck
    ? (en ? "Step-by-step eligibility & cutoff verification" : "படிப்படியான தகுதி & கட்-ஆஃப் சரிபார்ப்பு")
    : (stages[currentIdx] ? (en ? stages[currentIdx].title[1] : stages[currentIdx].title[0]) : "");

  const stepFraction = isCheck
    ? (en ? "100% Completed" : "100% முடிந்தது")
    : (en ? `${progressPercent}% Completed` : `${progressPercent}% முடிந்தது`);

  const hasState = Object.values(state).some((val) => val !== null);

  const pillsHtml = stages.map((stage, idx) => {
    const isCompleted = isCheck || (currentIdx >= 0 && idx < currentIdx);
    const isCurrent = !isCheck && idx === currentIdx;
    const statusClass = isCurrent ? "current" : isCompleted ? "completed" : "upcoming";
    const label = en ? stage.label[1] : stage.label[0];
    const prefix = isCurrent ? "● " : isCompleted ? "✓ " : `${stage.num}. `;
    const fullText = `${prefix}${label}`;

    if (!hasState) {
      return `<a href="/journey?step=${stage.id}${en ? "&amp;lang=en" : ""}" class="stepper-stage-item ${statusClass}" ${isCurrent ? 'aria-current="step"' : ""}>${fullText}</a>`;
    }
    return `<form action="/journey${en ? "?lang=en" : ""}" method="post" style="display:inline;margin:0;"><input type="hidden" name="state" value="${escape(JSON.stringify(state))}"><button type="submit" name="navigate" value="${stage.id}" class="stepper-stage-item ${statusClass}" ${isCurrent ? 'aria-current="step"' : ""}>${fullText}</button></form>`;
  }).join("");

  return `
    <div class="journey-stepper-card" role="region" aria-label="${en ? "5-Step Guidance Roadmap" : "5 படிகள் வழிகாட்டல் வரைபடம்"}">
      <div class="stepper-header-row">
        <div class="stepper-progress-info">
          <span class="stepper-step-pill">${stepBadge}</span>
          <span class="stepper-title-text">${stepTitle}</span>
        </div>
        <span class="stepper-count-tag">${stepFraction}</span>
      </div>
      <div class="stepper-progress-bar" role="progressbar" aria-valuenow="${progressPercent}" aria-valuemin="0" aria-valuemax="100" aria-label="${en ? "Overall progress" : "ஒட்டுமொத்த முன்னேற்றம்"}">
        <div class="stepper-progress-fill" style="width: ${progressPercent}%;"></div>
      </div>
      <nav class="stepper-stages-nav" aria-label="${en ? "Guidance roadmap navigation" : "வழிகாட்டல் படிகள் வழிசெலுத்தல்"}">
        ${pillsHtml}
      </nav>
    </div>
  `;
}

function makeJourneyNav(language: "ta" | "en") {
  return (page: "awareness" | "study" | "compare" | "route" | "prepare" | "check", label: string, state: JourneyState, primary = false): string => {
    if (Object.values(state).every((value) => value === null)) return link(`/journey?step=${page}${language === "en" ? "&amp;lang=en" : ""}`, label, primary);
    return `<form action="/journey${language === "en" ? "?lang=en" : ""}" method="post"><input type="hidden" name="state" value="${escape(JSON.stringify(state))}"><button class="${primary ? "primary" : ""}" name="navigate" value="${page}" type="submit">${label}</button></form>`;
  };
}

